/* Asset-only renderer. Simulation never depends on pixels or animation frames. */
(function(root){'use strict';
const G={x:250,y:85,w:80,h:96,cols:9,rows:5,width:1100,height:600};
class Renderer{
 constructor(manifest,images){this.manifest=manifest;this.images=images;}
 static async load(progress=()=>{}){let manifest=root.__ASSET_MANIFEST__;if(!manifest){const res=await fetch('assets/manifest.json');if(!res.ok)throw Error('素材清单加载失败');manifest=await res.json();}const files=[...new Set(['lawn.jpg',...Object.values(manifest).map(m=>m.file),...Object.values(LawnGame.PLANTS).map(p=>'card-'+p.asset+'.png'),'shovelIcon.png',...(root.LawnUI?.FILES||[]).map(f=>'ui/'+f)])];const images={};let done=0;await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>{images[file]=im;progress(++done/files.length);resolve();};im.onerror=()=>reject(Error('素材加载失败：'+file));im.src=root.__ASSET_URLS__?.[file]||'assets/'+file;})));return new Renderer(manifest,images);}
 sprite(g,name,x,y,w,h,time=0,frame=null){const m=this.manifest[name];if(!m)return;const im=this.images[m.file];if(!im)return;let f=frame;if(f===null){let ms=((time%m.period)+m.period)%m.period*1000;if(m.durations?.length){f=0;while(f<m.frames-1&&ms>=m.durations[f])ms-=m.durations[f++];}else f=Math.floor(time*10)%m.frames;}f=Math.max(0,Math.min(m.frames-1,f));g.drawImage(im,(f%m.cols)*m.w,Math.floor(f/m.cols)*m.h,m.w,m.h,x,y,w,h);}
 plant(g,p,opacity=1){const d=LawnGame.PLANTS[p.type],x=G.x+(p.col+.5)*G.w,foot=G.y+p.row*G.h+87;let w=71,h=71,name=d.asset,frame=null;
 if(p.type==='sun'){w=73;h=74;}if(p.type==='wall'){w=65;h=73;const base=p.hp/p.max<.33?34:p.hp/p.max<.66?17:0;frame=base+Math.floor(p.age*8)%Math.min(16,base===34?14:16);}
 if(p.type==='tall'){w=83;h=119;name=p.hp/p.max<.33?'TallnutCracked2':p.hp/p.max<.66?'TallnutCracked1':'TallNut';}if(p.type==='cherry'){w=100;h=73;}if(p.type==='jalapeno'){w=65;h=85;}if(p.type==='potato'){w=100;h=70;frame=p.age<14?0:1+Math.floor(p.age*7)%9;}
 const birth=Math.min(1,p.age/.2);g.save();g.globalAlpha=opacity;if(p.hit>0)g.globalAlpha*=.55+.45*Math.sin(p.age*60)**2;let recoil=(p.recoil||0)*12;this.sprite(g,name,x-w/2-recoil,foot-h*birth,w,h*birth,p.age,frame);if(p.type==='potato'&&p.age<14){g.fillStyle='#493c29a0';g.beginPath();g.ellipse(x,foot-6,18,5,0,0,Math.PI*2);g.fill();g.fillStyle='#bf3430';g.beginPath();g.arc(x,foot-12,3,0,Math.PI*2);g.fill();}g.restore();}
 sunPosition(s,t){let y=G.y+s.row*G.h+35;if(s.source==='sky'){const f=Math.min(1,s.age/1.3);y=-35+(y+35)*(1-(1-f)**2);}else y-=Math.sin(Math.min(1,s.age/.6)*Math.PI)*25;return{x:G.x+s.x*G.w,y:y+Math.sin(t*2+s.id)*2};}
 draw(g,game,selected,hover,{grid=false}={}){g.clearRect(0,0,G.width,G.height);if(root.LawnUI&&this.images['ui/background1unsodded.jpg'])root.LawnUI.ground(this,g,game);else g.drawImage(this.images['lawn.jpg'],0,0,1400,600);let t=game.time;
 if(grid){g.save();g.strokeStyle='#fff9d744';g.lineWidth=1;g.setLineDash([4,5]);for(let c=0;c<=9;c++){g.beginPath();g.moveTo(G.x+c*G.w,G.y);g.lineTo(G.x+c*G.w,G.y+5*G.h);g.stroke();}for(let r=0;r<=5;r++){g.beginPath();g.moveTo(G.x,G.y+r*G.h);g.lineTo(G.x+9*G.w,G.y+r*G.h);g.stroke();}g.restore();}
 if(hover&&selected&&game.rows.includes(hover.row)){let valid=selected==='shovel'?!!game.at(hover.row,hover.col):game.canPlace(selected,hover.row,hover.col).ok;g.fillStyle=valid?'#ffffff29':'#cb292a39';g.fillRect(G.x+hover.col*G.w,G.y+hover.row*G.h,G.w,G.h);g.strokeStyle=valid?'#fff5b280':'#ff8b80';g.lineWidth=2;g.strokeRect(G.x+hover.col*G.w+1,G.y+hover.row*G.h+1,G.w-2,G.h-2);if(selected!=='shovel'&&LawnGame.PLANTS[selected])this.plant(g,{type:selected,row:hover.row,col:hover.col,age:1,hp:300,max:300},.4);}
 for(let r=0;r<5;r++){const m=game.mowers[r];if(m.ready||m.active)this.sprite(g,'LawnMower',G.x+m.x*G.w-32,G.y+r*G.h+40,65,52,t);}
 for(let r=0;r<5;r++){
  for(const p of game.plants.filter(p=>p.row===r))this.plant(g,p);
  for(const c of game.corpses.filter(c=>c.row===r)){const name=c.burn?'BoomDie':'ZombieDie';g.save();g.globalAlpha=Math.min(1,(1.5-c.age)*2);this.sprite(g,name,G.x+c.x*G.w-80,G.y+r*G.h-56,166,144,Math.min(c.age,this.manifest[name].period-.01));g.restore();}
  for(const e of game.enemies.filter(e=>e.row===r)){let armorGone=e.type!=='normal'&&e.hp<=200;let name=(armorGone?'Zombie':LawnGame.ENEMIES[e.type].asset)+(e.chewing?'Attack':'');g.save();if(e.hit>0)g.globalAlpha=.68;if(e.slow>0){g.filter='hue-rotate(125deg) saturate(0.7)';}this.sprite(g,name,G.x+e.x*G.w-80,G.y+r*G.h-56,166,144,e.age*(e.slow>0?.5:1));g.restore();}
 }
 for(const b of game.shots){this.sprite(g,b.ice?'SnowBullet':'Bullet',G.x+b.x*G.w-18,G.y+b.row*G.h+26,42,26,t);}
 for(const e of game.effects)if(!['collect','banner'].includes(e.kind))this.effect(g,e);
 for(const s of game.suns){const pos=this.sunPosition(s,t);g.save();g.globalAlpha=Math.min(1,s.life/2);this.sprite(g,'Sun',pos.x-29,pos.y-29,58,58,t);g.restore();}
 for(const e of game.effects)if(['collect','banner'].includes(e.kind))this.effect(g,e);
 g.save();g.fillStyle='#483824d9';g.font='bold 14px system-ui';g.textAlign='right';g.fillText(game.cfg.title,1080,592);g.restore();}
 effect(g,e){const x=G.x+(e.x||0)*G.w,y=G.y+(e.row||0)*G.h+50,q=1-e.life/e.total;g.save();g.globalAlpha=Math.min(1,e.life*5);if(e.kind==='boom'){this.sprite(g,'Boom',x-106,y-98,213,196,0,Math.min(this.manifest.Boom.frames-2,Math.floor(q*(this.manifest.Boom.frames-1))));}else if(e.kind==='fire'){this.sprite(g,'JalapenoAttack',G.x-10,y-80,755,131,0,Math.min(this.manifest.JalapenoAttack.frames-1,Math.floor(q*this.manifest.JalapenoAttack.frames)));}else if(e.kind==='hit'){this.sprite(g,'BulletHit',x-23,y-20,46,40,0);}else if(e.kind==='collect'){const f=1-(1-q)**2;this.sprite(g,'Sun',x+(100-x)*f-22,y+(25-y)*f-22,44,44,q);g.fillStyle='#fff7b5';g.strokeStyle='#594620';g.lineWidth=2;g.font='bold 17px system-ui';g.strokeText('+'+e.value,x-12,y-25-q*30);g.fillText('+'+e.value,x-12,y-25-q*30);}else if(e.kind==='banner'){g.globalAlpha=Math.min(1,q*5,e.life*2);g.textAlign='center';g.font='bold 36px system-ui';g.lineWidth=5;g.strokeStyle='#231f19';g.fillStyle='#dd3d2d';g.strokeText(e.text,590,310);g.fillText(e.text,590,310);}else{for(let i=0;i<8;i++){const a=i*Math.PI/4,r=25*q;g.fillStyle=i%2?'#705036':'#b79a5d';g.beginPath();g.ellipse(x+Math.cos(a)*r,y+30+Math.sin(a)*r+q*q*12,2,3,0,0,Math.PI*2);g.fill();}}g.restore();}
}
root.LawnRenderer={Renderer,G};
})(typeof globalThis!=='undefined'?globalThis:this);
